import { chromium } from 'playwright';

const stories = [
  'elements-zimminlinemessage--error-variant',
  'elements-zimminlinemessage--warning',
  'elements-zimminlinemessage--success',
  'commerce-productitem--with-error-message',
  'commerce-productitem--with-warning-message',
  'commerce-productitem--with-discount-label',
];

const browser = await chromium.launch();
for (const id of stories) {
  const page = await browser.newPage({ viewport: { width: 700, height: 500 } });
  await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1500);

  const result = await page.evaluate(() => {
    const roots = Array.from(document.querySelectorAll('[data-testid="zimm-inline-message"], [data-testid="zimm-discount-label"]'));
    return roots.map((root) => {
      const rootCs = getComputedStyle(root);
      const textEl = root.querySelector('p');
      const textCs = textEl ? getComputedStyle(textEl) : null;
      const svg = root.querySelector('svg');
      const svgRect = svg ? svg.getBoundingClientRect() : null;
      const textRect = textEl ? textEl.getBoundingClientRect() : null;
      return {
        testId: root.getAttribute('data-testid'),
        text: textEl?.textContent,
        rootColor: rootCs.color,
        rootGap: rootCs.gap,
        rootAlignItems: rootCs.alignItems,
        textFontSize: textCs?.fontSize,
        textFontWeight: textCs?.fontWeight,
        textLineHeight: textCs?.lineHeight,
        textColor: textCs?.color,
        hasIcon: !!svg,
        iconSize: svgRect ? { w: Math.round(svgRect.width), h: Math.round(svgRect.height) } : null,
        gapBetweenIconAndText: svgRect && textRect ? Math.round(textRect.left - svgRect.right) : null,
      };
    });
  });
  console.log(`\n=== ${id} ===`);
  console.log(JSON.stringify(result, null, 2));
  await page.close();
}
await browser.close();

